    print(f"\n{'='*50}")
    print(f"  {dataset_name}")
    print(f"{'='*50}")

    all_raw = {}
    for name, path in config_paths.items():
        records = load_jsonl(path)
        raw = [{"doc_id": r.get("doc_id", i), **stats_fn(r, *stats_fn_args)} for i, r in enumerate(records)]
        all_raw[name] = {r["doc_id"]: r for r in raw}
        print(f"  {name}: {len(records)} samples")

    configs = list(all_raw.keys())
    common_ids = set(all_raw[configs[0]].keys())
    for cfg in configs[1:]:
        common_ids &= set(all_raw[cfg].keys())
    common_ids = sorted(common_ids)
    print(f"  Common samples: {len(common_ids)}")

    all_stats = {}
